---
// PART 5 car and front garden: the two-tone 1950s car on the driveway, two palms, the cactus cluster on the gravel bed,
// a dead bush on the sand and the low mailbox (plan.md PARTS 5; elements 20, 21, 22). Ticks 20, 21, 22.
import { car_50s, palm, saguaro, barrel_cactus, mailbox, DEAD_BUSH, DIRT } from "../vocab.mjs";

// The cactus helpers set sand at y=0 under each plant. site.mjs (an earlier part) owns the bed's ground, so the sand
// goes in only where the ground is still plain dirt; a cell site already paved (gravel or sand) is left as it is.
const onGround = (g) => new Proxy(g, {
  get(target, prop) {
    if (prop === "set") {
      return (x, y, z, block, state) => {
        if (y > 0 || target.blockAt(x, 0, z) === `minecraft:${DIRT}`) target.set(x, y, z, block, state);
        return g;
      };
    }
    const v = Reflect.get(target, prop);
    return typeof v === "function" ? v.bind(target) : v;
  },
});

// vocab's palm sets plain jungle_leaves, which decay once the trunk is gone; plan.md wants them persistent
const persistCrown = (g, x, z) => {
  for (let y = 6; y <= 7; y++) for (let dx = -2; dx <= 2; dx++) for (let dz = -2; dz <= 2; dz++) {
    if (g.blockAt(x + dx, y, z + dz) === "minecraft:jungle_leaves") g.set(x + dx, y, z + dz, "jungle_leaves", { persistent: "true" });
  }
};

export function build(g) {
  car_50s(g);                       // x=3..5 z=1..7 on the driveway, nose to the street
  palm(g, 12, 3);                   // in the north gravel bed
  persistCrown(g, 12, 3);
  palm(g, 30, 4);                   // in the east gravel bed; its crown meets the roof's eave, the helper skips filled cells
  persistCrown(g, 30, 4);
  const desert = onGround(g);
  saguaro(desert, 26, 3, 3);        // tallest, with one arm on the west side
  saguaro(desert, 24, 2, 2);
  barrel_cactus(desert, 28, 2);
  barrel_cactus(desert, 23, 4);
  barrel_cactus(desert, 29, 4);
  g.set(25, 1, 6, DEAD_BUSH);       // a dead bush on the open sand, clear of the cactus bed
  mailbox(g, 9, 1);                 // low post and box at the head of the driveway
}
----
// PART 6 pool, patio and garden details (plan.md step 6, elements 23, 24, 26): kidney_pool in the RESERVED cells with
// liner, water and quartz coping; three loungers and a patio table on the patio (z=26..28, y=1); a palm at (29,31);
// garden_lamp posts flanking the entry path and two by the pool; short_grass scattered over the back lawns.
// Every write goes into air only (earlier parts' blocks are locked), so an occupied cell is skipped, not replaced.
import { SAND, SHORT_GRASS, kidney_pool, lounger, patio_table, palm, garden_lamp } from "../vocab.mjs";

const GRASS = "minecraft:grass_block";

// a view that keeps only the writes into air: kidney_pool's coping lands on deck cells the patio already paved (locked)
function airOnly(g) {
  const view = new Proxy(g, {
    get(target, prop) {
      if (prop === "set") return (x, y, z, ...rest) => { if (target.isAir(x, y, z)) target.set(x, y, z, ...rest); return view; };
      const v = Reflect.get(target, prop);
      return typeof v === "function" ? v.bind(target) : v;
    },
  });
  return view;
}

export function build(g) {
  // the kidney pool: floor and liner at y=-2..-1 are below the grid (dropped by build.mjs), water and coping at y=0
  kidney_pool(airOnly(g));

  // patio furniture on the smooth_stone patio (y=0), standing at y=1
  lounger(g, 12, 26, "x");
  lounger(g, 15, 26, "x");
  lounger(g, 25, 26, "x");
  patio_table(g, 20, 27);

  // palm in the back lawn, outside the deck and the pool
  palm(g, 29, 31);

  // garden lamps: two flanking the entry path on the sand, two on the lawn by the pool
  for (const [x, z] of [[17, 5], [21, 5], [10, 30], [25, 30]]) {
    if (g.isAir(x, 0, z)) g.set(x, 0, z, SAND);
    if (g.isAir(x, 1, z) && g.isAir(x, 2, z) && g.isAir(x, 3, z)) garden_lamp(g, x, z);
  }

  // short grass on about one lawn cell in five, picked by a fixed hash so every run gives the same lawn
  for (let x = 0; x < 34; x++) {
    for (let z = 26; z <= 33; z++) {
      if (g.blockAt(x, 0, z) !== GRASS || !g.isAir(x, 1, z)) continue;
      if ((((x * 73856093) ^ (z * 19349663)) >>> 0) % 5 === 0) g.set(x, 1, z, SHORT_GRASS);
    }
  }
}
---
  put(g, x + 1, 1, z, ...B.stairs("smooth_quartz", "west", "bottom"));
}

/** garden_lamp(x,z): dark_oak_fence at y=1..2, standing lantern (hanging=false) at y=3. */
export function garden_lamp(g, x, z) {
  for (const y of [1, 2]) put(g, x, y, z, ...B.fence("dark_oak"));
  put(g, x, 3, z, LANTERN, { hanging: "false" });
}

/** hung_lantern(x,z,y=4): lantern hanging=true under a beam or the ceiling (y=5). */
export function hung_lantern(g, x, z, y = 4) {
  put(g, x, y, z, LANTERN, { hanging: "true" });
}

